    public static string Resolve(ushort mapId, ReadOnlySpan<byte> rawNameBytes, string? script = null)
    {
        if (!string.IsNullOrWhiteSpace(script))
        {
            int dot = script.LastIndexOf('.');
            string key = dot >= 0 ? script[(dot + 1)..] : script;
            if (ByScriptPrefix.TryGetValue(key, out string? byScript)) return byScript;
        }
        ReadOnlySpan<byte> trimmed = rawNameBytes;
        int nul = trimmed.IndexOf((byte)0);
        if (nul >= 0) trimmed = trimmed[..nul];
        string hex = Convert.ToHexString(trimmed).ToLowerInvariant();
        if (ByMapAndName.TryGetValue((mapId, hex), out string? mapped)) return mapped;
        if (ByUniqueName.TryGetValue(hex, out mapped)) return mapped;
        if (trimmed.Length > 31)
        {
            string hex31 = Convert.ToHexString(trimmed[..31]).ToLowerInvariant();
            if (ByMapAndName.TryGetValue((mapId, hex31), out mapped)) return mapped;
            if (ByUniqueName.TryGetValue(hex31, out mapped)) return mapped;
        }
        return Encoding.Latin1.GetString(trimmed).Trim();
    }
